from datetime import datetime, timezone
from sqlalchemy.ext.asyncio import AsyncSession
from sqlalchemy import select
from app.models.project_access import ProjectAccess #ok maybe ill change the model names to be like this?
from app.services.audit_log_service import write_audit_log #interesting

#below is very different from the crap i made before.
